import{_ as t,o,c as s,a2 as r}from"./chunks/framework.CGSzHL4z.js";const p=JSON.parse('{"title":"Hidden things","description":"","frontmatter":{},"headers":[],"relativePath":"reference/hidden.md","filePath":"reference/hidden.md","lastUpdated":1791952279000}'),n={name:"reference/hidden.md"};function i(a,e,l,d,c,h){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="hidden-things" tabindex="-1">Hidden things <a class="header-anchor" href="#hidden-things" aria-label="Permalink to &quot;Hidden things&quot;">​</a></h1><p>Easy-to-miss controls and tricks.</p><h3 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h3><ul><li><strong><code>Space</code> does two jobs</strong>: tap it to play or pause, hold it and drag to pan. The status bar says &quot;Space held: drag to pan&quot; while it is armed.</li><li><strong><code>Alt</code> means &quot;no snapping&quot; everywhere</strong>: scrubbing the ruler (lands between frames), key and marker drags, region and scene-end drags, scale handles, sound and effect bar edges, ease handles (Alt ignores the Shift snap). Spread uses <code>Alt</code> for exact ticks instead of whole frames.</li><li><strong>Double click does a lot</strong>: a row header keys the row at the playhead; empty lane space selects all of that row&#39;s keys (on an action track, all its blocks); a main key selects everything under it; a marker flag renames it; a sound&#39;s right edge clears its trim; a bar grip resets to the emitter&#39;s own Lifetime; a row-height grip resets the row&#39;s height; a scene in the list renames it.</li><li><strong>Tab is a three-stop cycle</strong>: Dope sheet, Ease view, Channels view, back to the dope sheet (not just two views). In Split it swaps the lower part between Ease and Channels.</li><li><strong>The Ease and Channels tabs under the Search box</strong> open that view under the dope rows; clicking the open one closes it.</li><li><strong><code>E</code></strong> opens the Ease window for the selected keys without going to the Ease view.</li><li><strong>The value axis zooms</strong>: scroll over the 44 px axis in the curve graph to zoom values at the pointer (Ctrl+Shift+wheel does it anywhere on the graph).</li><li><strong><code>Ctrl+Shift</code>+wheel</strong> shrinks or grows dope sheet rows (compact rows are 20 px, normal 24).</li><li><strong>Click the status bar&#39;s items</strong>: Snap opens the snap menu, Auto-key toggles, the frame rate opens its menu, the length opens &quot;Type a length... / End at the playhead / End at the last key&quot; (type <code>2s</code>, <code>72f</code> or a number in the ruler&#39;s units), the particle-cap message opens Settings &gt; Effects.</li><li><strong>Retiming scales</strong>: dragging the scale handles, or shortening the scene, never deletes keys. Insert/Remove time in the ruler menu shifts everything after a point; &quot;Remove the loop region&#39;s time&quot; cuts the loop region out.</li><li><strong><code>Shift+K</code></strong> (or a double click on an actor&#39;s row header) keys a whole actor: every joint of a rig, even the ones not keyed yet, never its root (key that from the root row); the root of anything else.</li><li><strong>Frame 0 is kept for you</strong>: the first key you write after frame 0 on a track also keys frame 0 with the value from before you animated it (Settings &gt; Posing &gt; Key frame 0 when it&#39;s missing; Auto-key chevron).</li><li><strong>Call rows</strong>: <code>K</code> or a double click on an <code>Emit()</code> / <code>Play()</code> row header keys a call at the playhead copying the key before it (an <code>Emit(20)</code> stays 20). Two <code>Play()</code> keys with different settings dropped on one frame both stay (stacked bars).</li><li><strong>Stacked bars can be re-arranged</strong>: drag a sound bar, burst bar or action block up or down to choose its lane; right click &gt; Reset lane to let it stack on its own.</li><li><strong>Sound bars</strong>: trim the start without moving the audio, stretch the speed with <code>Ctrl</code>+drag, fade with the hover grips, loop with the loop handles, and <strong>drag a key near a loud hit to snap onto the waveform&#39;s peak</strong> (amber snap line, &quot;snap: Roar peak&quot;). A sound row can be made taller (drag the header edge) for bigger waveforms. Scrubbing over a sound plays short snippets (Settings &gt; Audio) that end where the playhead&#39;s frame ends.</li><li><strong>Emitter bars</strong>: grips on an <code>Emit()</code> bar set that burst&#39;s particle life (the key keeps its own life); the grips on an emitter&#39;s stream band change the emitter&#39;s Lifetime property.</li><li><strong>Remove many tracks at once</strong>: Ctrl or Shift click several object or property headers, right click one: &quot;Remove N tracks from timeline&quot;.</li><li><strong>Mute / lock</strong> work per actor (Hub or the Timeline row), per joint and per property track. Muted rows draw at 50% and are skipped in preview, playback and export.</li><li><strong>Paste to another actor</strong>: select exactly one other actor and paste (or use the key menu&#39;s &quot;Paste to another actor&quot;) to put copied keys on it; <strong>Paste mirrored</strong> swaps a joint&#39;s keys onto its partner with the flipped channels negated.</li><li><strong>Row stripes</strong> make a row&#39;s name line up with its keys; strength is tunable (View &gt; Row stripes, Settings &gt; Timeline).</li><li>The Timeline and the Hub set <strong>Studio&#39;s selection aside</strong> while the pointer is over them, so a stray Delete cannot delete your rig (a Cast row click selects the rig, which shows in the Explorer once the pointer leaves the Hub). If a stand-in is deleted anyway, a banner offers <strong>Restore</strong>.</li></ul><h3 id="viewport" tabindex="-1">Viewport <a class="header-anchor" href="#viewport" aria-label="Permalink to &quot;Viewport&quot;">​</a></h3><ul><li><strong><code>T</code></strong> switches between Move &amp; rotate and Resize; <strong><code>R</code></strong> cycles Local / Parent / World; <strong><code>Ctrl</code></strong> during a drag flips between Studio&#39;s snapping increments and free movement.</li><li><strong>Tap <code>P</code></strong> pins the picked parts; <strong>hold <code>P</code> and click</strong> pins a spot; <strong>hold <code>P</code> and click a floor or prop</strong> (with parts picked) anchors their pins to it so they ride along; <strong>Unanchor picked pins</strong> (the Pins menu, or the viewport&#39;s right-click <strong>Unanchor pin</strong>) lets them go of it, pinned where they are now; <strong><code>Shift+P</code></strong> clears.</li><li><strong>Hold <code>I</code></strong> to flip FK and IK for a drag; <strong><code>Ctrl+[</code> / <code>Ctrl+]</code></strong> change the IK chain length (even mid-drag).</li><li><strong>Hold <code>Tab</code></strong> to turn about any point of any part (27 snap points per part box); release and the gizmo goes back to the joint.</li><li><strong>Hold <code>J</code></strong> (or click the stopwatch) to retime keys by sliding their dots along a motion trail; <strong>double click a trail</strong> to add a key; <strong><code>Alt</code></strong> on a tangent handle breaks it.</li><li><strong>Click an effect model in the viewport</strong> (even an invisible, non-clickable holder part) to select it in Studio, then Add actor from selection. <strong><code>Alt</code>+click</strong> selects just the part.</li><li><strong><code>[</code> and <code>]</code></strong> walk up and down the picked joint&#39;s chain.</li><li><strong><code>Esc</code> or right click</strong> cancels any gizmo or resize drag and puts the pose back.</li><li>Poses are <strong>temporary until keyed</strong>: moving the playhead drops an unkeyed pose; Auto-key keys on release; <code>K</code> keys picked joints.</li><li>Onion ghosts, trails and pins all read the keys you have <strong>selected in the Timeline</strong>: select two or more keys to see the path and a ghost on each.</li></ul><h3 id="inspector" tabindex="-1">Inspector <a class="header-anchor" href="#inspector" aria-label="Permalink to &quot;Inspector&quot;">​</a></h3><ul><li><strong>Drag any number field</strong> to scrub it (<code>Shift</code> 10x finer, <code>Ctrl</code> whole numbers, <code>Esc</code> puts it back).</li><li><strong>Right click anywhere on a row</strong>: Key at playhead, Remove from timeline, Copy, Paste, Reset to default, Reset to value before animating.</li><li><strong><code>K</code> over a row</strong> keys it. The diamond cycles animate, key, remove key.</li><li><strong>Edits made in Studio&#39;s own Properties window</strong> to a property already on the Timeline are recorded (keyed with Auto-key on, a Changed pose with it off).</li><li><strong>Search covers the whole actor</strong>, not just the picked object; matches elsewhere are listed under &quot;Elsewhere on {actor}&quot; with a <strong>Show</strong> arrow.</li><li><strong>Select several objects</strong> (Timeline keys or rows, or the Explorer) and edit them together: Mixed values, per-part typing, one undo step.</li><li>A <strong>Decal id</strong> pasted into a texture field says &quot;Not an image: a Decal&quot;: paste the image&#39;s id instead (a Decal&#39;s Texture holds it). The palette lists the track&#39;s images and the actor&#39;s.</li><li>A NumberSequence / ColorSequence row has a <strong>one-value control</strong> before its preview.</li><li>Attributes of any type animate like properties; the <strong>Calls section</strong> keys methods.</li><li>Clicking a Timeline property row, a key, or a part in the viewport changes what the Inspector shows.</li><li><strong>An actor or its root row?</strong> Both show the actor&#39;s properties, but the Stack section lists every stacked row for the actor (its Timeline row or its own root picked) and only the root&#39;s stack when the Timeline&#39;s root row is the selected one.</li></ul><h3 id="editor-windows" tabindex="-1">Editor windows <a class="header-anchor" href="#editor-windows" aria-label="Permalink to &quot;Editor windows&quot;">​</a></h3><ul><li><strong><code>Enter</code> = OK, <code>Esc</code> = Cancel</strong>, and <code>Ctrl+Z</code> / <code>Ctrl+Y</code> step through the window&#39;s own changes (also the footer&#39;s Undo / Redo). Keep several windows open at once, up to 6 per kind.</li><li><strong>Click the sequence graph</strong> to add a point and keep dragging it; <strong>double click a gradient stop</strong> to edit its colour in its own picker; <strong>Presets</strong> replace the shape; the <strong>Saved strip</strong> keeps colours, gradients and sequences in the scene for every property.</li><li>A saved sequence larger than the current Range grows the Range to fit.</li></ul><h3 id="scenes-export-and-settings" tabindex="-1">Scenes, export and settings <a class="header-anchor" href="#scenes-export-and-settings" aria-label="Permalink to &quot;Scenes, export and settings&quot;">​</a></h3><ul><li><strong>Scenes can live in any folder</strong>: move a scene folder anywhere and it is still listed and saved there; Export&#39;s play line then starts with <code>AcesMotion.RegisterFolder(...)</code>.</li><li><strong>Scene &gt; Save as...</strong> makes a copy and opens it with its name ready to type; <strong>Duplicate</strong> copies without opening.</li><li><strong>Export &gt; Preview id</strong> makes a test AnimationId for the session so the rig plays the exported clip without uploading; after the first upload paste the id so you can pick &quot;Overwrite an existing asset...&quot; next time and keep the same id in games.</li><li><strong>Scene as text</strong> (Export) + <strong>Import &gt; Scene text</strong> moves a whole scene between places.</li><li><strong>Create N scenes / Save as model</strong> (Export &gt; AcesMotion runtime) split a multi-rig scene into one scene per rig and pack them for other games.</li><li><strong>Reset this group</strong> at the bottom of a Settings page restores that page&#39;s defaults (and its rebindable keys) after a confirm; it never touches your mirror rules or presets.</li><li><strong>Gizmo size</strong>: click the value on the slider to type one. <strong>Icon style</strong> switches every icon live.</li><li>Every control has a <strong>tooltip</strong>; a disabled control&#39;s tooltip says why. After the first tooltip, tooltips appear instantly while you move across neighbouring controls.</li></ul>',12)])])}const u=t(n,[["render",i]]);export{p as __pageData,u as default};
